"""Finalize a named publication run after the reviewer personally reads the rendered pages."""
import sys,hashlib,json,csv,shutil,re,platform
from pathlib import Path
H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def J(p):return json.loads(p.read_bytes())
def save(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=True,default=str)+'\n',encoding='utf8')
def main(src,root,v):
    obs=J(src/'observed.json');rr=J(src/'render/pages.json');review=J(v);assert review['commit']==obs['commit'] and review['reviewer']==obs['reviewer']
    assert rr['committed_pdf']==review['pdf_sha256'] and set(str(p['page']) for p in rr['pages'])==set(review['page_notes'])
    published=J(root.parent/'TEXT_T2_PUBLISHED.json');assert published['commit']==obs['commit'] and published['parent']==obs['parent'] and published['remote_parity']
    published_files={Path(n).relative_to(obs['paper_path']).as_posix():dict(entry,blob=entry['git_blob']) for n,entry in published['files'].items()}
    for n,entry in published_files.items():
        for k in ['sha256','blob','bytes']:assert entry[k]==obs['files'][n][k],(n,k)
    assert set(published_files)==set(obs['files'])
    nums=J(src/'TEXT_T3_NUMERIC_AND_FIGURE_AUDIT.json');math=J(src/'TEXT_T3_MATH_VERIFICATION.json');f=J(src/'findings_1_to_1.json');assert len(f)==26 and all(x['status']=='CORRECTED' for x in f.values())
    assert list(nums['bibliography']).count('Gershgorin1931')==1 and 'Gershgorin_Z_domain_exact_left_endpoints' in math
    paper=(src/'source/04_PAPER_A.tex').read_text(encoding='utf8')
    assert 'Gershgorin' in paper and 'Gershgorin1931' in paper
    for q in ['TEXT_T3_MATH_VERIFICATION.json','TEXT_T3_NUMERIC_AND_FIGURE_AUDIT.json']:shutil.copyfile(src/q,root/q)
    records={'T1_findings':f,'additional_F4_finding':{'id':'F4-01','status':'CORRECTED','location':'Proposition 1 and bibliography','first_candidate':'0ec9a3e93d03848334ce8c1e1499cf9da24f1ab4','test':'published 1931 source and Satz II p. 751, exact symbolic disc endpoints of RMR, independent vector/raster read of corrected proposition and ninth reference'}}
    save(root/'TEXT_T3_FINDINGS_CLOSURE.json',records)
    summary=J(src/'granular_ledger_checks.json')
    totals={'publication_files':len(obs['files']),'tex_files':len(obs['linked_inputs']),'legacy_claims':obs['revised_legacy_register_claim_count'],'baseline_crosswalk':obs['baseline_crosswalk_count'],'final_granular_claims':summary['final_rows'],'granular_evidence_hash_pairs':summary['source_evidence_hashes_checked'],'propositions':paper.count(r'\begin{proposition}'),'proofs':paper.count(r'\begin{proof}'),'printed_matrix_examples':4,'figure_captions':sum(t.count(r'\begin{figure}') for t in [(src/'source'/n).read_text(encoding='utf8') for n in obs['linked_inputs']]),'table_captions':sum(t.count(r'\begin{table}') for t in [(src/'source'/n).read_text(encoding='utf8') for n in obs['linked_inputs']]),'bibliographic_records':len(nums['bibliography']),'PDF_pages':len(rr['pages']),'graph_marks':{'cost_bound_markers':21,'bars':28,'diagnostic_cells':56},'original_points':len(nums['cohort']),'g3_negative_attempts':len(nums['G3_attempts']),'separately_hashed_original_or_QA_inputs':len(obs['evidence']),'canonical_T1_findings':len(f),'supplemental_T3_findings':1,'open_P0':0}
    reg=src/'source/TEXT_T2_CLAIM_TO_EVIDENCE.csv'
    with reg.open(encoding='utf-8-sig',newline='') as io:rows=list(csv.DictReader(io))
    meaningful=[x for x in rows if x['file'].endswith('.tex') and re.search(r'(?<![A-Za-z])\d+',x['verbatim_claim_or_expression'])]
    totals['TeX_ledger_entries_containing_numeric_literals_including_formula_constants']=len(meaningful)
    save(root/'TEXT_T3_RENDER_INSPECTION.json',dict(**review,page_evidence=rr['pages'],font_embedding=rr['fonts_embedded']))
    proofs=[
    'The series-admittance Laplacian cancels on ones; diagonal line charging can survive. The DCP gauge has no source stamp. The case has no eliminated nodes. The Schur statements for generalized elimination separately require PSD and range.',
    'The sum over nonnegative contracted edge quadratics and scaled row sums recovers the form of RMR. In a symmetric Z-matrix r_i(Mr)_i is the centre minus the absolute row radius, as in Gerschgorin (1931). Congruence transfers PSD. The two 2-by-2 fixed-scaling examples give opposite noninclusions.',
    'Every G3 edge block is PSD under directed nonnegative allocations and the product inequality. Summing the edge blocks and diagonal remainders recovers M. For an irreducible PSD Z-component the inverse image of ones (PD) or positive Perron kernel vector (singular) supplies r. Isolated nodes require nonnegative diagonal. Multiplying qij by qji reproduces the squared mutual coefficient. The printed RSOC first-coordinate factor 1/2 is essential.',
    'On common regional order and units, SPD symmetric Z with inverse nonnegative and p nonnegative gives G1=>M0 by multiplication, then M0=>G0 by the nonnegative-matrix row norm, similarity and congruence. All printed Zp, row products, determinant and eigenvalues agree on their own matrix. Singular S can yield an unbounded quotient below unless the range/PSD guards hold. An exposure-free S has empty quotient domain.',
    'M1 uses a physically enforced SPD Z floor and diagonal-only increments. Its inverse difference factors in the stated order. M2 uses nonnegative fixed unit-diagonal W and common nonnegative exposure, hence Wp>=p. The real W was set pre-M2 from a previous G2 state. There is no eligible real M1 case. A free rho bounded only from above can be zero and cannot supply the claimed conservative right-hand load. No decision-dependent inverse linearization is claimed.',
    'Only thermal event-bearing units have startup/shutdown windows. Connection and initial counts, storage chronology, hydro/PHS, DCP energy exchange, source credit once, incremental renewable burden on availability/nameplate, and the actual dispatch quota agree with the original scientific replay. Event prices multiply rated MW once and shutdown costs 0.2 times startup. Annual CAPEX plus once-weighted 168-hour OPEX has no yearlong operational guarantee.',
    'Checked the six BASE/G1 LP/MILP pairs plus both G2 rows. The lower bound and independently reconstructed feasible upper bound use the same annual-equivalent EUR2025 coordinate. All seven MILP intervals and LP lower markers, the three opposite-endpoint premiums and all table units were verified with Decimal. Finite incumbent gaps preclude inferring a global G1/G2 optimum order; diagnostic margins and undefined M0 hours stay distinct.',
    'Each of eight direct G3 attempts has its own code/case disposition. Original-space residual maxima across heterogeneous coordinates do not represent one physical-unit norm. The first MOSEK point has qualified negative checks without a synthetic scalar. The G2 witness gives a numerical primal upper bound on G0/G3, the fixed-W M2 relaxation gives a separate numerical M2 lower bound. The approximately 659.12 million EUR difference across models establishes no within-model optimality gap. Two M2 integer limits have no incumbent and the unqualified G0 ray supplies no lower bound.',
    'The DOI/publisher records for the eight original references and the digitized 1931 primary source were read. The article claims scope the novelty to this certificate comparison; empirical H3/H4 remain untested. Private data and source/model rights limit the public rebuild to the publication layer.']
    reviewtext='# Independent complete manuscript review\n\nReviewer /root/qa_r. Paper writer /root/governance. Mathematics reviewer /root/math_r. This reviewer did not author the revised manuscript, its figures or the production solver. The earlier independent F2 acceptance was reused with fresh primary-file hash checks; F4 did not run an optimizer.\n\nFinal Git commit '+obs['commit']+', parent '+obs['parent']+', scientific paper path '+obs['paper_path']+'. The observed-manifest audit read all Git objects directly. The technical sources were pinned to '+obs['technical_readonly']+' and the correction to the German source handoff was checked at a4c19e962e9f59f5b40cf05f8d0cee2f24a52a78.\n\n'+'\n\n'.join(proofs)+'\n\nThe canonical T1 ledger and F4-01 have individual independent dispositions in TEXT_T3_FINDINGS_CLOSURE.json. The five mutated TeX inputs, stale PDF identity, corrupt public data and unknown G3 attempt were rejected. Rebuilding from the public input alone reproduced each figure, generated TeX fragment and the finished PDF; the check also compared extracted text and rendered pixels on every page. The earlier first-candidate font-cache limitation is preserved in candidate01 and was resolved by using the correct package resources in an independent empty build.\n\n## Visual inspection\n\n'+'\n\n'.join(f'Page {i}. {s}' for i,s in review['page_notes'].items())+'\n'
    (root/'TEXT_T3_INDEPENDENT_FULL_MANUSCRIPT_REVIEW.md').write_text(reviewtext,encoding='utf8')
    (root/'TEXT_T3_F4_VERDICT.md').write_text(f"# F4_PASS — {obs['commit']}\n\nThe final published files in TEXT_T3_FINAL_PUBLICATION_MANIFEST.json passed TEXT_MATH, TEXT_RESULTS, TEXT_SCOPE, TEXT_BUILD and F4_INDEPENDENT. The independent reviewer, /root/qa_r, verified the {totals['final_granular_claims']} final granular entries and {totals['PDF_pages']} rendered pages, closed 26 T1 findings and the additional Gershgorin attribution, and found zero open P0 findings for the retained claims. No optimizer was run. The pass binds these exact Git blobs and the PDF SHA-256 {rr['committed_pdf']}. S-GOV ratification is pending. SUBMISSION_READY=false.\n",encoding='utf8')
    records_log=obs['processes']+[{'command':obs['argv'],'exit':0,'log_sha256':H(root/(src.name+'.log')),'note':'Observed successful process exit; original shell console archived.'}]
    (root/'TEXT_T3_PUBLICATION_AUDIT.log').write_text('\n'.join(json.dumps(r,ensure_ascii=True) for r in records_log)+'\n',encoding='utf8')
    obs['stage']='F4_PASS';obs['counts']=totals;obs['independent_outcome']='PAPER_F3_CORRECTED_F4_PASS_PENDING_SGOV';obs['submission_ready']=False
    obs['publication_receipt_sha256']=H(root.parent/'TEXT_T2_PUBLISHED.json');obs['canonical_finding_index_sha256']=H(root.parent/'ORCH/TEXT_T1_COMPLETE_FINDINGS.csv')
    obs['controls']=J(src/'publication_negative_controls.json');obs['reviewer_source_files']={p.name:H(p) for p in root.glob('f4_*.py')};obs['reviewer_artifacts']={p.name:H(p) for p in root.glob('TEXT_T3_*') if p.is_file() and p.name!='TEXT_T3_FINAL_PUBLICATION_MANIFEST.json'}
    obs['supplemental_ledger_receipt']={'path':str(src/'granular_ledger_checks.json'),'sha256':H(src/'granular_ledger_checks.json')}
    obs['separate_math_and_DATA_evidence']={str(p.relative_to(root.parent)):H(p) for p in [root.parent/'MATH/TEXT_T1_MATH_ORACLES.json',src/'source/TEXT_T2_MATH_ORACLE_RESULTS.json',root.parent/'ORCH/TEXT_T1_NUMERIC_ASSERTIONS.json']}
    save(root/'TEXT_T3_FINAL_PUBLICATION_MANIFEST.json',obs)
    print(json.dumps({'verdict':'F4_PASS','commit':obs['commit'],'counts':totals,'manifest':H(root/'TEXT_T3_FINAL_PUBLICATION_MANIFEST.json')},indent=2))
if __name__=='__main__':main(*map(Path,sys.argv[1:]))